# The default engine (pdflatex) cannot typeset Japanese, so the Japanese PDF is
# built with LuaLaTeX. Sphinx has no built-in LuaLaTeX+Japanese profile, so the
# few pieces it would otherwise get wrong are configured explicitly here. Latin
# body text keeps Sphinx's default fonts; Japanese glyphs are handled by
# LuaTeX-ja (and its bundled Harano Aji fonts).
if language == "ja":
    latex_engine = "lualatex"
    # Sphinx's default base classes for Japanese (jsbook/jsarticle) are
    # pLaTeX-only and abort under LuaLaTeX; use the LuaTeX-ja counterparts,
    # which load LuaTeX-ja and set up Japanese typesetting on their own.
    latex_docclass = {"manual": "ltjsbook", "howto": "ltjsarticle"}
    # With LuaTeX-ja doing the Japanese typesetting, drop polyglossia/babel:
    # their \setmainlanguage{japanese} demands a CJK-capable *main* font and
    # otherwise aborts the build against the Latin body font set by fontspec.
    latex_elements["polyglossia"] = ""
    latex_elements["babel"] = ""
    # For non-pdflatex engines Sphinx defaults the index builder to xindy, an
    # extra system dependency. The index here is Latin (tag/function names), so
    # use makeindex instead -- it ships with TeX Live (and is what the English
    # pdflatex build already uses), keeping the CI TeX install self-contained.
    latex_use_xindy = False

